/**
 * Convierte strings tipo "10:00:00 a.m." / "10:00:00 p.m." a "HH:mm"
 * Acepta también "10:00 a.m." (sin segundos).
 */
function convertirHora(horaStr) {
  if (!horaStr || typeof horaStr !== 'string') return null;

  // Normalizar: quitar espacios extra, pasar a minúsculas
  let s = horaStr.trim().toLowerCase();

  // Quitar puntos en el sufijo y espacios raros: "a.m." -> "am", "p.m." -> "pm"
  s = s.replace(/\./g, '');

  // Separar parte de tiempo y sufijo am/pm
  const match = s.match(/^(\d{1,2}:\d{2}(?::\d{2})?)\s*(am|pm)$/);
  if (!match) {
    // Si no coincide, intentemos sin sufijo (ya en 24h). Ej: "22:00:00"
    const m24 = s.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?$/);
    if (m24) {
      const h = m24[1].padStart(2, '0');
      const min = m24[2];
      return `${h}:${min}`;
    }
    // Formato desconocido
    return null;
  }

  const timePart = match[1]; // "10:00:00" o "10:00"
  const suffix = match[2];   // "am" o "pm"

  // Extraer horas y minutos
  const tm = timePart.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?$/);
  const hour12 = parseInt(tm[1], 10);
  const minutes = tm[2];

  // Convertir a 24h
  let hour24 = hour12 % 12; // 12 -> 0
  if (suffix === 'pm') hour24 += 12;
  const hh = String(hour24).padStart(2, '0');

  return `${hh}:${minutes}`;
}

