function generarIdUnico(timestampStr) {
  // Suponiendo que viene como "1/1/12 12:00:00"
  const [fechaStr, horaStr] = timestampStr.split(" ");
  const [dia, mes, anio] = fechaStr.split("/");

  // Ajusta el año: "12" → "2012"
  const anioCompleto = anio.length === 2 ? "20" + anio : anio;

  const isoStr = `${anioCompleto}-${mes.padStart(2,"0")}-${dia.padStart(2,"0")}T${horaStr}`;
  const fecha = new Date(isoStr);

  return (
    fecha.getFullYear().toString() +
    String(fecha.getMonth() + 1).padStart(2, "0") +
    String(fecha.getDate()).padStart(2, "0") +
    String(fecha.getHours()).padStart(2, "0") +
    String(fecha.getMinutes()).padStart(2, "0") +
    String(fecha.getSeconds()).padStart(2, "0")
  );
}


